import { useState } from 'react'
import { Check, Clock, Copy, DollarSign, ExternalLink, Plus, Save, Trash2 } from 'lucide-react'
import { AppLayout } from '@/components/layout'
import Button from '@/components/ui/Button'
import Input from '@/components/ui/Input'
import TimeInput from '@/components/ui/TimeInput'
import DateInput from '@/components/ui/DateInput'
import { Skeleton } from '@/components/ui/Skeleton'
import Badge from '@/components/ui/Badge'
import { supabase } from '@/lib/supabase'
import { toast } from '@/lib/toast'
import { confirm } from '@/lib/confirm'
import { useAuthContext } from '@/hooks/AuthProvider'
import { useTenant } from '@/hooks/useTenant'
import {
  useAvailabilityBlocks,
  useAvailabilitySchedules,
  useBookableModules,
  useCreateAvailability,
  useCreateAvailabilityBlock,
  useDeleteAvailability,
  useDeleteAvailabilityBlock,
  useDisableModuleForBooking,
  useEnableModuleForBooking,
  useUpdateModuleBookingConfig,
} from '@/hooks/useBooking'
import type { AvailabilitySchedule, BookableModule } from '@/services/booking'
import { DAYS_OF_WEEK } from './shared'
import '../Settings.css'
import './BookingScreen.css'

export default function BookingScreen() {
  const { user } = useAuthContext()
  const { tenant, loading: loadingTenant } = useTenant()
  const isOwner = user?.role === 'owner'

  const { data: schedules, isLoading: loadingSchedules } = useAvailabilitySchedules()
  const { data: modules, isLoading: loadingModules } = useBookableModules()

  const createAvailability = useCreateAvailability()
  const deleteAvailability = useDeleteAvailability()
  const enableModule = useEnableModuleForBooking()
  const disableModule = useDisableModuleForBooking()
  const updateModuleConfig = useUpdateModuleBookingConfig()

  // Form state para novo horário - agora com múltiplos dias
  const [selectedDays, setSelectedDays] = useState<number[]>([1, 2, 3, 4, 5]) // Seg a Sex por padrão
  const [newStart, setNewStart] = useState('09:00')
  const [newEnd, setNewEnd] = useState('18:00')

  // Form state para configurar módulo
  const [configuringModule, setConfiguringModule] = useState<BookableModule | null>(null)
  const [configDuration, setConfigDuration] = useState('60')
  const [configBuffer, setConfigBuffer] = useState('10')
  const [configPrice, setConfigPrice] = useState('')

  // Regras de agendamento (colunas do tenant)
  const [advanceMonths, setAdvanceMonths] = useState(String(tenant?.booking_advance_months ?? 2))
  const [minNoticeHours, setMinNoticeHours] = useState(
    String(tenant?.booking_min_notice_hours ?? 2)
  )
  const [savingRules, setSavingRules] = useState(false)

  const handleSaveRules = async () => {
    if (!tenant) return

    const months = parseInt(advanceMonths, 10)
    const notice = parseInt(minNoticeHours, 10)

    if (isNaN(months) || months < 1) {
      toast('Meses de antecedência deve ser pelo menos 1', 'error')
      return
    }
    if (isNaN(notice) || notice < 0) {
      toast('Antecedência mínima não pode ser negativa', 'error')
      return
    }

    setSavingRules(true)
    try {
      const { error } = await supabase
        .from('tenants')
        .update({
          booking_advance_months: months,
          booking_min_notice_hours: notice,
        })
        .eq('id', tenant.id)

      if (error) throw error
      toast('Regras de agendamento salvas!')
    } catch {
      toast('Erro ao salvar regras de agendamento', 'error')
    } finally {
      setSavingRules(false)
    }
  }

  const bookingUrl = tenant?.slug
    ? `${window.location.origin}/book/${tenant.slug}${user?.slug ? `/${user.slug}` : ''}`
    : ''

  const toggleDay = (dayValue: number) => {
    setSelectedDays(prev =>
      prev.includes(dayValue)
        ? prev.filter(d => d !== dayValue)
        : [...prev, dayValue].sort((a, b) => a - b)
    )
  }

  const handleAddSchedules = async () => {
    if (selectedDays.length === 0) {
      toast('Selecione pelo menos um dia', 'error')
      return
    }

    // Criar um schedule para cada dia selecionado
    for (const day of selectedDays) {
      await createAvailability.mutateAsync({
        day_of_week: day,
        start_time: newStart + ':00',
        end_time: newEnd + ':00',
      })
    }
  }

  const handleDeleteSchedule = async (schedule: AvailabilitySchedule) => {
    const confirmed = await confirm({
      message: 'Remover este horário?',
      confirmLabel: 'Remover',
      variant: 'danger',
    })
    if (confirmed) {
      deleteAvailability.mutate(schedule.id)
    }
  }

  const handleToggleModule = async (module: BookableModule) => {
    if (module.booking_service) {
      const confirmed = await confirm({
        message: `Desabilitar "${module.name}" do agendamento online?`,
        confirmLabel: 'Desabilitar',
        variant: 'danger',
      })
      if (confirmed) {
        disableModule.mutate(module.id)
      }
    } else {
      setConfiguringModule(module)
      setConfigDuration('60')
      setConfigBuffer('10')
      setConfigPrice('')
    }
  }

  const handleEnableModule = () => {
    if (!configuringModule) return

    enableModule.mutate(
      {
        moduleId: configuringModule.id,
        config: {
          duration_minutes: parseInt(configDuration, 10),
          buffer_minutes: parseInt(configBuffer, 10),
          price: configPrice ? parseFloat(configPrice) : null,
        },
      },
      {
        onSuccess: () => {
          setConfiguringModule(null)
        },
      }
    )
  }

  const handleUpdateModuleConfig = (
    module: BookableModule,
    field: 'duration' | 'buffer' | 'price',
    value: string
  ) => {
    if (!module.booking_service) return

    if (field === 'duration') {
      const duration = parseInt(value, 10)
      if (duration > 0) {
        updateModuleConfig.mutate({
          moduleId: module.id,
          config: { duration_minutes: duration },
        })
      }
    } else if (field === 'buffer') {
      const buffer = parseInt(value, 10)
      if (buffer >= 0) {
        updateModuleConfig.mutate({
          moduleId: module.id,
          config: { buffer_minutes: buffer },
        })
      }
    } else {
      updateModuleConfig.mutate({
        moduleId: module.id,
        config: { price: value ? parseFloat(value) : null },
      })
    }
  }

  const copyBookingUrl = () => {
    navigator.clipboard.writeText(bookingUrl)
    toast('Link copiado!')
  }

  // Agrupar horários por dia
  const schedulesByDay =
    schedules?.reduce(
      (acc, schedule) => {
        const day = schedule.day_of_week
        if (!acc[day]) acc[day] = []
        acc[day].push(schedule)
        return acc
      },
      {} as Record<number, AvailabilitySchedule[]>
    ) || {}

  if (loadingTenant) {
    return (
      <AppLayout title="Agendamento">
        <div className="settings-page">
          <Skeleton height="400px" />
        </div>
      </AppLayout>
    )
  }

  return (
    <AppLayout title="Agendamento" subtitle="Disponibilidade e reservas online">
      <div className="settings-page">
        <div className="settings-section">
          {/* Link de Agendamento */}
          <div className="settings-card">
            <h3>Link de Agendamento</h3>
            <p className="settings-description">
              Compartilhe este link com seus clientes para que eles possam agendar atendimentos
              online.
            </p>
            <div className="booking-link-container">
              <Input value={bookingUrl} disabled className="booking-link-input" />
              <Button variant="secondary" onClick={copyBookingUrl}>
                <Copy size={18} />
                Copiar
              </Button>
              <Button variant="secondary" onClick={() => window.open(bookingUrl, '_blank')}>
                <ExternalLink size={18} />
                Abrir
              </Button>
            </div>
          </div>

          {/* Regras de Agendamento (só owner) */}
          {isOwner && (
            <div className="settings-card">
              <h3>Regras de Agendamento</h3>
              <p className="settings-description">
                Defina a janela em que os clientes podem reservar horários online.
              </p>
              <div className="settings-form">
                <div className="settings-form-row">
                  <Input
                    label="Antecedência mínima (horas)"
                    type="number"
                    value={minNoticeHours}
                    onChange={e => setMinNoticeHours(e.target.value)}
                    min="0"
                    step="1"
                    hint="Tempo mínimo de aviso antes do horário. Ex: 2 = não permite reservar com menos de 2h."
                  />
                  <Input
                    label="Antecedência máxima (meses)"
                    type="number"
                    value={advanceMonths}
                    onChange={e => setAdvanceMonths(e.target.value)}
                    min="1"
                    step="1"
                    hint="Quantos meses completos à frente a agenda abre, além do mês atual. Ex: 2 (em setembro, libera outubro e novembro inteiros)."
                  />
                </div>
                <div className="settings-form-actions">
                  <Button onClick={handleSaveRules} disabled={savingRules}>
                    <Save size={18} />
                    {savingRules ? 'Salvando...' : 'Salvar regras'}
                  </Button>
                </div>
              </div>
            </div>
          )}

          {/* Horários de Atendimento */}
          <div className="settings-card">
            <h3>Horários de Atendimento</h3>
            <p className="settings-description">
              Configure os dias e horários em que você está disponível para atendimentos.
            </p>

            {/* Formulário para adicionar horário */}
            <div className="availability-form-v2">
              {/* Seletor de dias */}
              <div className="form-group">
                <label className="form-label">Dias da semana</label>
                <div className="days-selector">
                  {DAYS_OF_WEEK.map(day => (
                    <button
                      key={day.value}
                      type="button"
                      className={`day-chip ${selectedDays.includes(day.value) ? 'day-chip--selected' : ''}`}
                      onClick={() => toggleDay(day.value)}
                    >
                      {selectedDays.includes(day.value) && <Check size={14} />}
                      {day.short}
                    </button>
                  ))}
                </div>
              </div>

              {/* Horários */}
              <div className="availability-times">
                <TimeInput label="Início" value={newStart} onChange={setNewStart} />
                <TimeInput label="Fim" value={newEnd} onChange={setNewEnd} />
                <Button
                  onClick={handleAddSchedules}
                  disabled={createAvailability.isPending || selectedDays.length === 0}
                  className="availability-add-btn"
                >
                  <Plus size={18} />
                  Adicionar
                </Button>
              </div>
            </div>

            {/* Lista de horários */}
            {loadingSchedules ? (
              <Skeleton height="100px" />
            ) : Object.keys(schedulesByDay).length === 0 ? (
              <p className="settings-empty">Nenhum horário configurado</p>
            ) : (
              <div className="availability-list">
                {DAYS_OF_WEEK.map(day => {
                  const daySchedules = schedulesByDay[day.value]
                  if (!daySchedules || daySchedules.length === 0) return null

                  return (
                    <div key={day.value} className="availability-day">
                      <span className="availability-day-label">{day.label}</span>
                      <div className="availability-slots">
                        {daySchedules.map(schedule => (
                          <div key={schedule.id} className="availability-slot">
                            <span>
                              {schedule.start_time.slice(0, 5)} - {schedule.end_time.slice(0, 5)}
                            </span>
                            <button
                              className="availability-slot-remove"
                              onClick={() => handleDeleteSchedule(schedule)}
                              title="Remover"
                            >
                              <Trash2 size={14} />
                            </button>
                          </div>
                        ))}
                      </div>
                    </div>
                  )
                })}
              </div>
            )}
          </div>

          {/* Bloqueios de agenda */}
          <BlocksSettings />

          {/* Módulos para Agendamento (só owner) */}
          {isOwner && (
            <div className="settings-card">
              <h3>Serviços Disponíveis para Agendamento</h3>
              <p className="settings-description">
                Selecione quais módulos de terapia estarão disponíveis para agendamento online. Os
                módulos listados abaixo são os que você já criou em "Módulos".
              </p>

              {loadingModules ? (
                <Skeleton height="150px" />
              ) : !modules?.length ? (
                <div className="settings-empty-state">
                  <p>Nenhum módulo de terapia cadastrado.</p>
                  <p className="settings-empty-hint">
                    Vá em <strong>Módulos</strong> para criar seus tipos de atendimento.
                  </p>
                </div>
              ) : (
                <div className="bookable-modules-list">
                  {modules.map(module => (
                    <div
                      key={module.id}
                      className={`bookable-module ${module.booking_service ? 'bookable-module--enabled' : ''}`}
                    >
                      <div className="bookable-module-header">
                        <div
                          className="bookable-module-color"
                          style={{ background: module.color ?? undefined }}
                        />
                        <div className="bookable-module-info">
                          <span className="bookable-module-name">{module.name}</span>
                          {module.description && (
                            <span className="bookable-module-description">
                              {module.description}
                            </span>
                          )}
                        </div>
                        <button
                          className="bookable-module-toggle"
                          onClick={() => handleToggleModule(module)}
                        >
                          <Badge variant={module.booking_service ? 'success' : 'neutral'}>
                            {module.booking_service ? 'Habilitado' : 'Desabilitado'}
                          </Badge>
                        </button>
                      </div>

                      {/* Configuração quando habilitado */}
                      {module.booking_service && (
                        <div className="bookable-module-config">
                          <div className="bookable-module-field">
                            <Clock size={16} />
                            <input
                              type="number"
                              value={module.booking_service.duration_minutes}
                              onChange={e =>
                                handleUpdateModuleConfig(module, 'duration', e.target.value)
                              }
                              min="15"
                              step="5"
                              className="bookable-module-input"
                              title="Duração do atendimento"
                            />
                            <span className="bookable-module-unit">min</span>
                          </div>
                          <div className="bookable-module-field">
                            <Plus size={16} />
                            <input
                              type="number"
                              value={module.booking_service.buffer_minutes}
                              onChange={e =>
                                handleUpdateModuleConfig(module, 'buffer', e.target.value)
                              }
                              min="0"
                              step="5"
                              className="bookable-module-input bookable-module-input--small"
                              title="Intervalo entre atendimentos"
                            />
                            <span className="bookable-module-unit">intervalo</span>
                          </div>
                          <div className="bookable-module-field">
                            <DollarSign size={16} />
                            <span className="bookable-module-currency">R$</span>
                            <input
                              type="number"
                              value={module.booking_service.price || ''}
                              onChange={e =>
                                handleUpdateModuleConfig(module, 'price', e.target.value)
                              }
                              min="0"
                              step="0.01"
                              placeholder="0,00"
                              className="bookable-module-input"
                              title="Preço"
                            />
                          </div>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {/* Modal de configuração de módulo */}
          {configuringModule && (
            <div className="settings-modal-overlay" onClick={() => setConfiguringModule(null)}>
              <div className="settings-modal settings-modal--sm" onClick={e => e.stopPropagation()}>
                <h3>Habilitar para Agendamento</h3>
                <p className="settings-modal-description">
                  Configure as informações de agendamento para{' '}
                  <strong>{configuringModule.name}</strong>
                </p>

                <div className="settings-form">
                  <div className="settings-form-row">
                    <Input
                      label="Duração (min)"
                      type="number"
                      value={configDuration}
                      onChange={e => setConfigDuration(e.target.value)}
                      min="15"
                      step="5"
                    />
                    <Input
                      label="Intervalo (min)"
                      type="number"
                      value={configBuffer}
                      onChange={e => setConfigBuffer(e.target.value)}
                      min="0"
                      step="5"
                    />
                  </div>
                  <Input
                    label="Preço (opcional)"
                    type="number"
                    value={configPrice}
                    onChange={e => setConfigPrice(e.target.value)}
                    placeholder="0,00"
                    min="0"
                    step="0.01"
                  />
                </div>

                <div className="settings-modal-actions">
                  <Button variant="secondary" onClick={() => setConfiguringModule(null)}>
                    Cancelar
                  </Button>
                  <Button onClick={handleEnableModule} disabled={enableModule.isPending}>
                    {enableModule.isPending ? 'Habilitando...' : 'Habilitar'}
                  </Button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  )
}

// ============================================================
// Blocks Settings (bloqueios da própria agenda)
// ============================================================

function BlocksSettings() {
  const { data: blocks, isLoading } = useAvailabilityBlocks()
  const createBlock = useCreateAvailabilityBlock()
  const deleteBlock = useDeleteAvailabilityBlock()

  const [date, setDate] = useState('')
  const [allDay, setAllDay] = useState(true)
  const [start, setStart] = useState('09:00')
  const [end, setEnd] = useState('12:00')
  const [reason, setReason] = useState('')

  const handleAdd = async () => {
    if (!date) {
      toast('Selecione uma data', 'error')
      return
    }
    if (!allDay) {
      if (start >= end) {
        toast('O horário final deve ser maior que o inicial', 'error')
        return
      }
    }
    await createBlock.mutateAsync({
      date,
      start_time: allDay ? null : start + ':00',
      end_time: allDay ? null : end + ':00',
      reason: reason.trim() || null,
    })
    setReason('')
  }

  const handleDelete = async (id: string) => {
    const confirmed = await confirm({
      message: 'Remover este bloqueio?',
      confirmLabel: 'Remover',
      variant: 'danger',
    })
    if (confirmed) deleteBlock.mutate(id)
  }

  const fmtDate = (d: string) => {
    try {
      return new Date(d + 'T12:00:00').toLocaleDateString('pt-BR')
    } catch {
      return d
    }
  }

  return (
    <div className="settings-card">
      <h3>Bloqueios da Minha Agenda</h3>
      <p className="settings-description">
        Bloqueie datas ou horários da <strong>sua própria</strong> agenda (férias, compromissos,
        folgas). Só afeta os seus atendimentos — não bloqueia os outros terapeutas. Os horários
        bloqueados somem para os clientes na página de agendamento.
      </p>

      <div className="settings-form">
        <div className="settings-form-row">
          <div className="form-group">
            <label className="form-label">Data</label>
            <DateInput value={date} onChange={setDate} />
          </div>
          <div className="form-group">
            <label className="form-label">Tipo</label>
            <div className="days-selector">
              <button
                type="button"
                className={`day-chip ${allDay ? 'day-chip--selected' : ''}`}
                onClick={() => setAllDay(true)}
              >
                {allDay && <Check size={14} />}
                Dia inteiro
              </button>
              <button
                type="button"
                className={`day-chip ${!allDay ? 'day-chip--selected' : ''}`}
                onClick={() => setAllDay(false)}
              >
                {!allDay && <Check size={14} />}
                Faixa de horário
              </button>
            </div>
          </div>
        </div>

        {!allDay && (
          <div className="availability-times">
            <TimeInput label="Início" value={start} onChange={setStart} />
            <TimeInput label="Fim" value={end} onChange={setEnd} />
          </div>
        )}

        <Input
          label="Motivo (opcional)"
          value={reason}
          onChange={e => setReason(e.target.value)}
          placeholder="Ex.: Férias, compromisso pessoal"
        />

        <div className="settings-form-actions">
          <Button onClick={handleAdd} disabled={createBlock.isPending || !date}>
            <Plus size={18} />
            Adicionar bloqueio
          </Button>
        </div>
      </div>

      {isLoading ? (
        <Skeleton height="80px" />
      ) : !blocks?.length ? (
        <p className="settings-empty">Nenhum bloqueio cadastrado</p>
      ) : (
        <div className="blocks-list">
          {blocks.map(b => (
            <div key={b.id} className="block-item">
              <div className="block-item-info">
                <span className="block-item-date">{fmtDate(b.date)}</span>
                <span className="block-item-time">
                  {b.start_time && b.end_time
                    ? `${b.start_time.slice(0, 5)} – ${b.end_time.slice(0, 5)}`
                    : 'Dia inteiro'}
                </span>
                {b.reason && <span className="block-item-reason">{b.reason}</span>}
              </div>
              <button
                className="availability-slot-remove"
                onClick={() => handleDelete(b.id)}
                title="Remover"
              >
                <Trash2 size={14} />
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}
